@startuml

class Doctor {
  + practitionerNumber : int
  + fullName : string
  + address : string
  + phoneNumber : string
  + signature : string
}

class Patient {
  + healthNumber : string
  + firstName : string
  + lastName : string
  + dateOfBirth : date
  + address : string
  + phoneNumber : string
}

class Requisition {
  + validFrom : date
  + repetitionCount : int
  + repetitionInterval : string
}

class Test {
  + name : string
  + duration : time
  + isWalkIn : boolean
  + requiresSampleDropOff : boolean
}

class TestGroup {
  + name : string
}

class Lab {
  + address : string
  + registrationNumber : string
  + businessHoursStart : time
  + businessHoursEnd : time
  + cancellationFee : double
}

class Appointment {
  + confirmationNumber : string
  + date : date
  + startTime : time
  + endTime : time
}

class TestResult {
  + resultValue : string
  + report : string
}

Doctor "1" -- "*" Requisition : prescribes
Patient "1" -- "*" Requisition : receives
Requisition "1" -- "1..*" Test : contains
Test "*" -- "1" TestGroup : belongs to
Doctor "0..1" -- "0..*" TestResult : views
Patient "1" -- "0..*" TestResult : views
Patient "1" -- "0..*" Appointment : makes
Requisition "1" -- "0..1" Appointment : scheduled for
Lab "1" -- "0..*" Appointment : hosts
Lab "1" -- "0..*" Test : offers

@enduml

